glitch_title_effect.javascript:
document.querySelectorAll('.glitch-title a').forEach(title => {
  title.addEventListener('mouseover', () => {
    if (!title.dataset.original) title.dataset.original = title.innerText;
    let iterations = 0;
    const interval = setInterval(() => {
      title.innerText = title.innerText.split('')
        .map((char, index) => {
          if (index < iterations) return title.dataset.original[index];
          return String.fromCharCode(65 + Math.floor(Math.random() * 26));
        })
        .join('');
      if (iterations >= title.dataset.original.length) clearInterval(interval);
      iterations += 1/2; // Velocidade de revelação — 1/3 = lento, 1/2 = médio, 1 = rápido
    }, 30); // Intervalo em ms entre frames do glitch
  });
});

typewriter_effect.javascript:
const typeWriter = (el) => {
  const text = el.innerHTML;
  el.innerHTML = '';
  let i = 0;
  const interval = setInterval(() => {
    if (i < text.length) { el.innerHTML += text.charAt(i); i++; }
    else clearInterval(interval);
  }, 30);
};

