cookie_banner_pixel.javascript:
(function() {
  const banner = document.getElementById('retro-cookie-banner');
  const btn = document.getElementById('accept-cookies-btn');
  const key = 'softload_cookie_accepted';

  const init = () => {
    if (!localStorage.getItem(key)) {
      setTimeout(() => {
        banner.style.display = 'block';
        setTimeout(() => banner.classList.add('show-banner'), 50); // 50ms para transição CSS
      }, 1500);
    }
    btn.addEventListener('click', () => {
      localStorage.setItem(key, 'true');
      banner.classList.remove('show-banner');
      setTimeout(() => { banner.style.display = 'none'; }, 500);
    });
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else { init(); }
})();

newsletter_ajax_formsubmit.javascript:
guildForm.addEventListener('submit', function(e) {
  e.preventDefault();
  const btn = guildForm.querySelector('button');
  const originalText = btn.innerText;
  btn.innerText = 'LOADING...';
  btn.style.opacity = '0.7';
  btn.disabled = true;

  fetch(guildForm.getAttribute('action'), {
    method: 'POST',
    body: new FormData(guildForm),
    headers: { 'Accept': 'application/json' }
  })
  .then(response => {
    if (response.ok) {
      guildForm.style.display = 'none';
      successMsg.style.display = 'block';
    } else throw new Error();
  })
  .catch(() => {
    errorMsg.style.display = 'block';
    btn.innerText = 'TRY_AGAIN';
    btn.style.opacity = '1';
    btn.disabled = false;
  });
});

padronizacao_automatica_gadgets.css:
/* Cartucho automático: sidebar e footer */
.sidebar .widget, .footer .widget {
  background: #fff;
  border: var(--border-pixel);
  box-shadow: 6px 6px 0px #000;
  padding: 20px;
  margin-bottom: 30px;
  overflow: hidden;
}

/* Título do gadget estilo 'status screen' RPG */
.widget h2.title {
  font-family: var(--font-pixel);
  font-size: 0.7rem;
  color: #000;
  border-bottom: 4px double #000;
  padding-bottom: 10px;
  margin-bottom: 15px;
  text-transform: uppercase;
  line-height: 1.4;
}

/* Cursor RPG antes de cada item de lista */
.widget-content ul li::before {
  content: '>';
  font-family: var(--font-pixel);
  color: var(--primary);
  margin-right: 10px;
  font-size: 0.6rem;
  animation: blink 1.5s steps(2) infinite;
}

/* Links dentro de gadgets */
.widget-content a { color: #333; text-decoration: none; transition: color 0.2s, padding-left 0.2s; }
.widget-content a:hover { color: var(--primary); padding-left: 5px; }

