reveal_observer_combinado.javascript:
const revealObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.classList.add('active');
      const tw = entry.target.querySelector('[data-typewriter]');
      if (tw && !tw.classList.contains('typed')) {
        typeWriter(tw);
        tw.classList.add('typed');
      }
    }
  });
}, { threshold: 0.1 });

// Garante que artigos do Blog widget também recebem o reveal
document.querySelectorAll('.reveal, article').forEach(el => {
  el.classList.add('reveal');
  revealObserver.observe(el);
});
